{"title":"Moving a document to another observation scope","speed":2000,"elements":[{"id":"root","type":"group","children":["client","api","bank"],"layout":{"direction":"row","gap":48,"align":"center"}},{"id":"client","type":"rectangle","content":[{"type":"title","text":"Client"},{"type":"code","text":"PATCH /documents/chat-s1
{
 "observation_scopes":
 "shared"
}"}]},{"id":"api","type":"group","label":{"title":"update_document"},"children":["check","doc"],"layout":{"direction":"column","gap":28,"align":"stretch"}},{"id":"check","type":"diamond","content":[{"type":"title","text":"Scopes moved?"},{"type":"subtitle","text":"per memory, resolved"}]},{"id":"doc","type":"cylinder","content":[{"type":"title","text":"Document"},{"type":"subtitle","text":"retain_params"}]},{"id":"bank","type":"group","label":{"title":"Memory Bank"},"children":["facts","obs"],"layout":{"direction":"column","gap":28,"align":"stretch"}},{"id":"facts","type":"cylinder","content":[{"type":"title","text":"Facts"}]},{"id":"obs","type":"cylinder","content":[{"type":"title","text":"Observations"}]},{"id":"send","type":"arrow","route":"curved","start":{"id":"client"},"end":{"id":"check"},"label":{"text":"PATCH"}},{"id":"save","type":"arrow","route":"curved","start":{"id":"check"},"end":{"id":"doc"},"label":{"text":"save scope"}},{"id":"rescope","type":"arrow","route":"curved","start":{"id":"check"},"end":{"id":"facts"},"label":{"text":"rescope"}},{"id":"rebuild","type":"arrow","route":"curved","start":{"id":"facts"},"end":{"id":"obs"},"label":{"text":"consolidate"},"quiet":true}],"scenes":[{"label":"combined → shared","beats":[{"show":{"facts":[{"tag":"world","tone":"blue","text":"Alice prefers dark roast","meta":"session:s1 · combined"}],"obs":[{"tag":"scope","tone":"gray","text":"Alice likes dark roast","meta":"[session:s1]"}]},"say":"Session s1 was retained under the default scoping: its observation sits in its own scope."},{"edges":{"edge":"send","data":"shared"},"say":"The document is moved to the shared scope."},{"edges":"rescope","light":["check"],"show":{"facts":[{"tag":"world","tone":"blue","text":"Alice prefers dark roast","meta":"session:s1 · shared","mark":"↻"}],"obs":[{"tag":"scope","tone":"red","text":"Alice likes dark roast","meta":"[session:s1]","mark":"deleted"}]},"say":"Its scope moved: the old observation goes and the fact is queued again. Its tag stays."},{"edges":"save","show":{"doc":[{"text":"observation_scopes","meta":"shared","mark":"new","mono":true}]},"say":"The new scope is saved on the document, so a reprocess keeps it."},{"edges":"rebuild","ms":2600,"show":{"obs":[{"tag":"scope","tone":"green","text":"Alice likes dark roast","meta":"untagged · all sessions","mark":"new"}]},"say":"Consolidation rebuilds it in the shared scope, where every session's facts meet."}]},{"label":"same scope, nothing moves","beats":[{"edges":{"edge":"send","data":"[[session:s1]]"},"show":{"obs":[{"tag":"scope","tone":"gray","text":"Alice likes dark roast","meta":"[session:s1]"}]},"say":"combined over [session:s1] and [[session:s1]] resolve to the same scope."},{"light":["check"],"show":{"facts":[{"tag":"world","tone":"blue","text":"Alice prefers dark roast","meta":"consolidated","mark":"✓"}],"obs":[{"tag":"scope","tone":"gray","text":"Alice likes dark roast","meta":"[session:s1]","mark":"kept"}]},"say":"Nothing moved: no observation is deleted and nothing is queued."}]}]}
